import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水天需","description":"周易折中 - 水天需","frontmatter":{"title":"水天需","description":"周易折中 - 水天需"},"headers":[],"relativePath":"zh/classics/zhezhong/011.md","filePath":"zh/classics/zhezhong/011.md"}'),h={name:"zh/classics/zhezhong/011.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="水天需" tabindex="-1">水天需 <a class="header-anchor" href="#水天需" aria-label="Permalink to “水天需”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>序卦曰：蒙者，蒙也，物之稚也。物稚不可不飬也，故受之以需。需者，饮食之道也。夫物之㓜稚，必待飬而成。飬物之所需者，饮食也，故曰需者饮食之道也。云上于天，有蒸润之象，饮食所以润益于物，故需为饮食之道，所以次蒙也。卦之大意须待之义，序卦取所湏之大者耳。乾健之性必进者也，乃处坎险之下，险为之阻，故须待而后进也。</p><p>需：有孚，光亨，贞吉。利涉大川。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>需待也，以干遇坎。乾健坎险，以刚遇险而不遽进，以䧟于险，待之义也。孚，信之在中者也。其卦九五以坎体中实，阳刚中正而居尊位，为有孚得正之象。坎水在前，乾健临之，将涉水而不轻进之象。故占者为有所待而能有信，则光亨矣；若又得正则吉，而利渉大川。正固无所不利，而渉川尤贵于能待，则不欲速而犯难也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>需者湏待也。以二体言之，干之刚健上进而遇险，未能进也，故为需待之义。以卦才言之，五居君位，为需之主，有刚健中正之徳而诚信充实于中，中实有孚也。有孚则光明而能亨通，得贞正而吉也。以此而需，何所不济？虽险无难矣，故利渉大川也。凡贞吉，有既正且吉者，有得正则吉者，当辨也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云 ：需者宁耐之意。以刚遇险，时节如此，只得宁耐以待之。且如渉川者，多以不能宁耐致覆溺之祸，故需卦首言利渉大川。</p></li><li><p>项氏安世曰 ：需非终不进也，抱实而遇险，有待而后进也。凡待者皆以其中有可待之实也。我实有之，但能少待，必有光亨之理。若其无之，何待之有？故曰需有孚光亨。光亨者不可以盈，必敬慎以终之，故曰贞吉。信能行此，则其待不虚，其进不溺，故曰利渉大川。有孚光亨贞吉者，需之道也；利渉大川者，需之效也。</p></li><li><p>胡氏炳文曰 ：需而无实无光，且亨之时，需而非正则无吉，且利之理。世有心虽诚实而处事或有未正者，故曰孚又曰贞。</p></li><li><p>林氏希元曰 ：凡人作事皆责成于目前，其间多有阻碍而目前不可成者，其势不容于不待。然不容不待者，其心多非所乐，其待也未必出于中诚，不免于急迫觊望之意。如此则懐抱不开，胸中许多暗昧抑塞而不光明豁逹。故圣人特发有孚之义，盖遇事势之未可为，即安于义命从容以待机㑹而不切切焉以厚觊望，则其待也出于真实而非虚假矣。如此则心逸日休，胸襟洒落而无滞碍，不亦光明豁逹乎？然使心安于需而事或未出于正，则将来亦未必可成。必也所需之事皆出于正而无行险侥幸之为，则功深而效得，时动而事起，向者之所需而今皆就绪矣，故吉。</p></li></ul><p>象曰：云上于天，需；君子以饮食宴乐</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>云上于天，无所复为，待其阴阳之和而自雨。尔事之当需者，亦不容更有所为，但饮食宴乐，俟其自至而已。一有所为，则非需也。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>云气蒸而上升于天，必待阴阳和洽然后成雨。云方上于天，未成雨也，故为须待之义。阴阳之气交感而未成雨泽，犹君子畜其才德而未施于用也。君子观云上于天，需而为雨之象，懐其道德，安以待时。饮食以养其气体，宴乐以和其心志，所谓居易以俟命也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：不言“天上有云”，而言“云上于天”者，若是“天上有云”，无以见欲雨之义。故云“云上于天”，是天之欲雨，待时而落，所以明需。</p></li><li><p>胡氏瑗曰 ：饮食者，所以养身也；宴乐者，所以宁神也。是亦乐天知命，居易俟时耳。</p></li><li><p>朱子语类 ：需待也，以饮食宴乐谓更无所为，待之而已。待之须有至时，学道者亦犹是也。</p></li><li><p>吴氏澄曰 ：宴者，身安而他无所营；作乐者，心愉而他无所谋虑也。饮食则素其位，而宴乐则不愿乎外也。</p></li><li><p>谷氏家杰曰 ：云上于天，而后可以待雨。君子有为于前，而后可以待治。不然，不几于坐废乎？</p></li></ul><p>彖曰：需，须也，险在前也。刚健而不陷，其义不困穷矣。</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>此以卦徳释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>需之义须也，以险在于前，未可遽进，故需待而行也。以干之刚健而能需待，不轻动，故不陷于险，其义不至于困穷也。刚健之人，其动必躁，乃能需待而动，处之至善者也。故夫子赞之云，其义不困穷矣。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰：需者，坎险在前，须而后进也。惟刚则内有所主，故能需；惟健则动不可御，故能济。</p></li><li><p>蔡氏清曰：以刚遇险而不遽进以陷于险者，盖阴柔不能宁耐，乾刚则沈毅不苟而能宁耐。所谓“干天下之至健”也，徳行恒易以知险。</p></li></ul><p>需有孚，光亨贞吉，位乎天位以正中也。利涉大川，往有功也。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体及两象释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>五以刚实居中为孚之象，而得其所需，亦有为孚之义。以乾刚而至诚，故其徳光明而能亨通，得贞正而吉也。所以能然者，以居天位而得正中也。居天位指五，以正中兼二言，故云正中。既有孚而贞正，虽涉险阻，往则有功也。需道之至善也，以乾刚而能需，何所不利？</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>谷氏家杰曰：此卦合坎干成需，惟干易而知险，故曰刚健曰正中。见有天徳者能需也。</li></ul><p>初九：需于郊，利用恒，无咎。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>郊旷逺之地，未近于险之象也。而初九阳刚，又有能常于其所之象，故戒占者能如是则无咎也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>需者以遇险故需而后进，初最逺于险，故为需于郊。郊旷逺之地也，处于旷逺，利在安守其常，则无咎也。不能安常，则躁动犯难，岂能需于逺而无过也？</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：难在于坎，初九去难既逺，故待于郊。郊者，境上之地，去水逺也。恒，常也。逺难待时以避其害，故宜保守其常，所以无咎。</p></li><li><p>梁氏寅曰 ：需下三爻以去险逺近为吉凶。初以阳处下，最逺于险，故为需于郊之象。郊荒逺之地也，而君子安处焉，故云利用恒。</p></li></ul><p>象曰：需于郊，不犯难行也；利用恒，无咎，未失常也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>处旷远者不犯冒险难而行也。阳之为物，刚健上进者也。初能需待于旷远之地，不犯险难而进，复宜安处不失其常，则可以无咎矣。虽不进而志动者，不能安其常也。君子之需时也，安静自守，志虽有须而恬然若将终身焉，乃能用常也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>孙氏质卿曰 ：不犯难而行便是常，不失常便是恒德。人惟中无常主，或为才能所使，或为意气所动，或为事势所激，虽犯难而不顾耳。所以不失常最难，饮食宴乐不失常也。若能不失常，更有何事？</li></ul><p>九二：需于沙，小有言，终吉。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>沙则近于险矣，言语之伤亦灾害之小者，渐进近坎，故有此象。刚中能需，故得终吉。戒占者当如是也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>坎为水，水近则有沙。二去险渐近，故为需于沙。渐近于险难，虽未至于患害，已小有言矣。凡患难之辞大小有殊，小者至于有言，言语之伤至小者也。二以刚阳之才而居柔守中，寛裕自处，需之善也。虽去险渐近而未至于险，故小有言语之伤而无大害，终得其吉也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：沙是水旁之地，去水渐近，故难稍近，而小有言。但履健居中以待要㑹，终得其吉也。</p></li><li><p>胡氏炳文曰 ：初最逺坎，利用恒乃无咎；九二渐近坎，小有言矣，而曰终吉者。初九以刚居刚，恐其躁急，故虽逺险犹有戒辞；九二以刚居柔，寛而得中，故虽近险而不害其为吉。</p></li></ul><p>象曰：需于沙衍，在中也；虽小有言，以吉终也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>衍，宽意。以宽居中，不急进也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>衍，宽绰也。二虽近险，而以宽裕居中，故虽小有言语及之，终得其吉。善处者也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏简曰 ：衍在中者，言胸中宽衍平夷，初不以进动其心，亦不以小言动其心。夫如是，终吉。以九二得其道故也。</li></ul><p>九三：需于泥，致寇至。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>泥将䧟于险矣，寇则害之大者。九三去䧟愈近，而过刚不中，故其象如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>泥逼于水也，既进逼于险，当致寇难之至也。三刚而不中，又居健体之上，有进动之象，故致寇也。苟非敬慎，则致䘮败矣。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰 ：泥则切近水矣，险已近而又以刚用刚而进逼之，是招致寇难之至也。</p></li><li><p>龚氏焕曰 ：郊、沙、泥之象，视坎水逺近而为言者也。易之取象如此。</p></li></ul><p>象曰：需于泥，灾在外也；自我致寇，敬慎不败也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>外谓外卦。敬慎不败，发明占外之占，圣人示人之意切矣。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三切逼上体之险难，故云灾在外也。灾，患难之通称，对眚而言则分也。三之致寇，由己进而迫之，故云自我致寇。自己致，若能敬慎量宜而进，则无丧败也。需之时，须而后进也，其义在相时而动，非戒其不得进也，直使敬慎毋失其宜耳。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：问敬慎，曰：“敬字大，慎字细。如人行路，一直恁地去便是敬；前面险处，防有吃跌便是慎。慎是惟恐有失之之意。如思虑两字，思是恁地思去，虑是怕不恁地底意思。”</p></li><li><p>项氏安世曰 ：寇虽在外，然亦不自至，我有以致之则至。我敬慎而无失，则虽与之逼亦无败理。</p></li><li><p>丘氏富国曰 ：坎险在外，未尝逼人，由人急于求进，自逼于险以致祸败。象以“自我”释之，明致灾之由不在他人也。</p></li></ul><p>六四：需于血，出自穴。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>血者杀伤之地，穴者险䧟之所。四交坎体，入乎险矣，故为需于血之象。然柔得其正，需而不进，故又为出自穴之象。占者如是，则虽在伤地，而终得出也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四以阴柔之质，处于险而下，当三阳之进，伤于险难者也，故云需于血。既伤于险难，则不能安处，必失其居，故云出自穴。穴，物之所安也。顺以从时，不竞于险难，所以不至于凶也。以柔居阴，非能竞者也。若阳居之，则必凶矣。盖无中正之徳，徒以刚竞于险，适足以致凶耳。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类问 ：程传释穴为“物之所安”，曰：“穴是陷处，唤作所安不得。柔得正了，需而不进，故能出于坎陷。”</p></li><li><p>杨氏启新曰 ：刚者能需，柔亦能需，何也？刚柔皆有善恶。刚之需，犹干之健而知险也；柔之需，犹坤之简而知阻也。</p></li></ul><p>象曰：需于血，顺以听也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四以阴柔居于险难之中，不能固处，故退出自穴。盖阴柔不能与时竞，不能处则退，是顺从以听于时，所以不至于凶也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰 ：六四入险而伤，然不言吉凶何也？能需而退听故也。易之为道，无所不通。虽如四之入险而伤，其处之亦有道。六与四皆柔，故有顺听之象。</p></li><li><p>吴氏澄曰 ：谓六四柔顺以听从于九五也。</p></li><li><p>胡氏炳文曰 ：三能敬，则虽迫坎之险而不败；四能顺，则虽陷坎之险而可出。敬与顺，固处险之道也。</p></li></ul><p>九五：需于酒食，贞吉。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>酒食宴乐之具，言安以待之。九五阳刚中正，需于尊位，故有此象。占者如是而贞固，则得吉也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五以阳刚居中得正，位乎天位，克尽其道矣。以此而需，何需不获？故宴安酒食以俟之，所湏必得也。既得贞正，而所需必遂，可谓吉矣。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏维岳曰 ：《系辞》曰：“需者，饮食之道也。”象曰：“君子以饮食宴乐。”爻曰：“需于酒食”，以治道言，使斯民乐其乐而利其利，期治于必世，百年之后而不为近功者，湏待之义也。</p></li><li><p>乔氏中和曰 ：九五之贞吉也，岂徒以酒食云哉？险而不䧟，中自持也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>需之为义最广，其大者莫如王道之以乆而成，化而不急于浅近之功；圣学之以寛而居徳，而不入于正助之弊。卦惟九五，刚健中正以居尊位，是能尽需之道者，故彖传特举此爻以当彖辞之义；而大象传又特取此爻爻辞以蔽需义之全。盖继屯䝉之后，既治且教，而所谓休飬生息，使之乐乐而利利，渐仁摩义，使之世变而风移者，其在于需乎？观需之卦而不知此爻之义，但以诸爻处险之偏乎一义者概之，则需与蹇、困何异哉？</p><p>象曰：酒食贞吉，以中正也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>需于酒食而贞且吉者，以五得中正而尽其道也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>梁氏寅曰 ：言以中正，见其饮宴者非耽乐也。</p></li><li><p>张氏振渊曰 ：内多欲则有求治太急之患，德惟中正，所以需合于贞而得吉。中正即孚贞意，是推原所以能需处。</p></li></ul><p>上六：入于穴，有不速之客三人来，敬之终吉。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>阴居险极，无复有需，有陷而入穴之象。下应九三，九三与下二阳需极并进，为不速客三人之象。柔不能御而能顺之，有敬之之象。占者当陷险中，然于非意之来，敬以待之，则得终吉也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>需以险在前，需时而后进。上六居险之终，终则变矣，在需之极，乆而得矣。阴止于六，乃安其处，故为入于穴。穴所安也，安而既止，后者必至。不速之客三人，谓下之三阳。干之三阳，非在下之物，需时而进者也。需既极矣，故皆上进，不速不促之而自来也。上六既需得其安处，群刚之来，苟不起忌疾忿竞之心，至诚尽敬以待之，虽甚刚暴，岂有侵陵之理？故终吉也。或疑以阴居三阳之上，得为安乎？曰：三阳干体，志在上进，六阴位非所止之正，故无争夺之意，敬之则吉也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：入于穴，险极而陷之象；速者，主召客之辞；三人，干三阳之象。下三阳非皆与上应也，有不速之象。上柔顺，有敬之之象。上独不言需，险之极无复有需也。外卦险体，二阴皆有穴象。四出自穴，而上则入于穴何哉？六四柔正能需，犹可出于险，故曰出者，许其将然也；上六柔而当险之终，无复能需，惟入于险而已，故曰入者，言其已然也。然虽已入于险，非意之来，敬之终吉。君子未尝无处险之道也。</p></li><li><p>薛氏瑄曰 ：有不速之客三人来，敬之终吉，处横逆之道也。</p></li><li><p>谷氏家杰曰 ：三居下卦之终而示之以敬，上居上卦之终而又示之以敬，则知处需者贵敬也。</p></li></ul><p>象曰：不速之客来，敬之终吉；虽不当位，未大失也</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>以阴居上，是为当位。言不当位，未详。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>不当位，谓以阴而在上也。爻以六居阴为所安，象复尽其义，明阴宜在下而居上为不当位也。然能敬慎以自处，则阳不能陵，终得其吉。虽不当位，而未至于大失也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吕氏祖谦曰 ：需初九、九五、二爻之吉固不待言，至于馀四爻，如二则小有言终吉，如三之象则曰敬慎不败，四之象则曰顺以听也，上则曰有不速之客三人来，敬之终吉。大抵天下之事，若能款曲停待，终是少错。</p></li><li><p>蔡氏清曰 ：虽不当位，谓其阴居险极，正与困上六“困于葛藟”未当也一般。</p></li></ul><p>站长备注：</p><h3 id="关于-不当位" tabindex="-1">关于“不当位” <a class="header-anchor" href="#关于-不当位" aria-label="Permalink to “关于“不当位””">​</a></h3><p>蔡氏说法站长极为认同，曾根据“当位”、“不当位”、“位当”、“位不当”等辞做统计了一个 统计列表 ，大多数都是讨论“爻的阴阳”与“位”是否匹配，唯独此爻是特例，此爻阴居阴位，按照固定的手法去讨论，这里的“不当位”是矛盾的，所以左右揣摩衡量就有了蔡氏一样的观点，今见之，与古人不谋而合！</p><p>爻辞和象曰，是从卦象代表的含义和爻位代表的含义而来，而孔夫子作《象》时，不拘于固定的“位”所代表的含义，而是从整体去考虑，是脱离固定研究手法，直指道理和实际。这里的“不当位”是从坎象而来，是居坎之极，下三阳为“不速之客”，居坎险之地，又遇刚暴的三阳（乾），是危之极，是所处的位置不当，所以象曰“虽不当位”意思是“虽处不恰当的位置”，而非指“爻的阴阳”与“位”是否匹配。</p><p>每一个爻并不是独立的，而是和其它爻有联系的。一个爻的吉凶不是单从自身而言，而是和周遭的爻形成的局面而言。易的道理是以形会意，用简单的符号组合来阐述蕴含的道理，阴阳符号和六位是固定的，是具象化的形体，如果呆板的拘泥于手法，就是把《易》完全学成了“形而下”。</p><h3 id="关于敬之" tabindex="-1">关于敬之 <a class="header-anchor" href="#关于敬之" aria-label="Permalink to “关于敬之”">​</a></h3><p>《诗经·敬之》：敬之敬之，天维显思，命不易哉。无曰高高在上，陟降厥士，日监在兹。维予小子，不聪敬止。日就月将，学有缉熙于光明。佛时仔肩，示我显德行。</p><p>译文：要警戒要警戒，上天监察最明显，保持天命真困难。不要说天高高在上，每天监视着下界，人世间它看得最分明。我虽年幼初登基，聪明戒慎莫放弃。只要天天有进步，学问就会很光明。群臣辅我担大任，示我治国好德行。</p><p>《诗经》传为孔子编订，所以引用更加有说服力。按《诗经》注解云， 敬：通“儆”，警戒。之：语气词。 同类词语比如“杀鸡儆猴”、“以儆效尤”、“惩一儆百”、“惩一儆众”...都体现了警戒、告诫的意味。</p><p>这些道理无非就是一个核心，上爻面对“不速之客三人来”应该戒备，警戒。与通俗理解的“敬之”为“尊敬谨慎”相比，言辞更加严厉和迫切，强调了警觉的紧迫性和严肃性。（2024年3月10日，河北邯郸三名初中生杀害同学一案曝光，曾为受害人占卜得此爻）。</p><p>总论</p><ul><li>蒋氏悌生曰：需待也，以刚健之才遇险陷在前，当容忍待时。用柔而主静，若不度时势，恃刚忿躁而骤进，取败亡必矣。初九去险尚逺，以用恒免咎；九二渐近险，亦以用柔守中而终吉；九三已迫于险，象言敬慎不败；六四已伤于险，以柔而不竞能出自穴；上六险䧟之极，亦以能敬终吉。然则需待之时，能含忍守敬，皆可以免祸。需之时义大矣。</li></ul>',123)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
